U+0323, U+0329, U+1EA0-1EF9, U+20AB;\n}\n/* latin-ext */\n@font-face {\n  font-family: 'Archivo';\n  font-style: normal;\n  font-weight: 600;\n  font-stretch: 100%;\n  font-display: swap;\n  src: url(\"fecb85c6-0068-4539-a0f8-299e54331695\") format('woff2');\n  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;\n}\n/* latin */\n@font-face {\n  font-family: 'Archivo';\n  font-style: normal;\n  font-weight: 600;\n  font-stretch: 100%;\n  font-display: swap;\n  src: url(\"cf2b00ae-563b-476d-ae0e-982b8dd7260d\") format('woff2');\n  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\n/* vietnamese */\n@font-face {\n  font-family: 'Archivo';\n  font-style: normal;\n  font-weight: 800;\n  font-stretch: 100%;\n  font-display: swap;\n  src: url(\"50888715-8742-4520-a449-8fa344897966\") format('woff2');\n  unicode-range: U+0102-0103, U+0110-0111, U+0128-0129, U+0168-0169, U+01A0-01A1, U+01AF-01B0, U+0300-0301, U+0303-0304, U+0308-0309, U+0323, U+0329, U+1EA0-1EF9, U+20AB;\n}\n/* latin-ext */\n@font-face {\n  font-family: 'Archivo';\n  font-style: normal;\n  font-weight: 800;\n  font-stretch: 100%;\n  font-display: swap;\n  src: url(\"fecb85c6-0068-4539-a0f8-299e54331695\") format('woff2');\n  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;\n}\n/* latin */\n@font-face {\n  font-family: 'Archivo';\n  font-style: normal;\n  font-weight: 800;\n  font-stretch: 100%;\n  font-display: swap;\n  src: url(\"cf2b00ae-563b-476d-ae0e-982b8dd7260d\") format('woff2');\n  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\n\n\n:root {\n  --color-bg: #f3f2f2;\n  --color-surface: #eae9e9;\n  --color-text: #201e1d;\n  --color-accent: #ec3013;\n  --color-accent-2: #e15b47;\n  --color-divider: color-mix(in srgb, #201e1d 40%, transparent);\n\n  /* Tonal ramps — generated in OKLCH on one shared lightness scale, so the\n     same step of any role matches the others in visual value. */\n  --color-neutral-100: #f8f4f4;\n  --color-neutral-200: #eae7e7;\n  --color-neutral-300: #d7d3d3;\n  --color-neutral-400: #bab6b6;\n  --color-neutral-500: #9b9797;\n  --color-neutral-600: #7d7979;\n  --color-neutral-700: #605d5d;\n  --color-neutral-800: #444141;\n  --color-neutral-900: #2d2b2b;\n\n  --color-accent-100: #fff2ef;\n  --color-accent-200: #ffe0d9;\n  --color-accent-300: #ffc4b8;\n  --color-accent-400: #ff9783;\n  --color-accent-500: #ff563c;\n  --color-accent-600: #dd2b0f;\n  --color-accent-700: #ae1800;\n  --color-accent-800: #7c1405;\n  --color-accent-900: #4d170e;\n\n  --color-accent-2-100: #fff2ef;\n  --color-accent-2-200: #ffe0da;\n  --color-accent-2-300: #ffc4b9;\n  --color-accent-2-400: #ff9784;\n  --color-accent-2-500: #ef6853;\n  --color-accent-2-600: #c94b39;\n  --color-accent-2-700: #9e3526;\n  --color-accent-2-800: #71261b;\n  --color-accent-2-900: #471d16;\n\n  --font-heading: \"Archivo\", system-ui, sans-serif;\n  --font-heading-weight: 800;\n  --font-body: \"Archivo\", system-ui, sans-serif;\n\n  --space-1: 4.0px;\n  --space-2: 8.0px;\n  --space-3: 12.0px;\n  --space-4: 16.0px;\n  --space-6: 24.0px;\n  --space-8: 32.0px;\n\n  --radius-sm: 0px;\n  --radius-md: 0px;\n  --radius-lg: 0px;\n\n  /* Elevation — derived from the ground: soft ink-tinted shadows on a\n     light theme, a hairline edge + ambient darkness on a dark one. */\n  --shadow-sm: 0 1px 2px color-mix(in srgb, #2d2b2b 14%, transparent);\n  --shadow-md: 0 3px 10px color-mix(in srgb, #2d2b2b 16%, transparent);\n  --shadow-lg: 0 12px 32px color-mix(in srgb, #2d2b2b 22%, transparent);\n}\n\nbody {\n  background: var(--color-bg);\n  color: var(--color-text);\n  font-family: var(--font-body);\n}\nh1, h2, h3, h4 { font-family: var(--font-heading); font-weight: var(--font-heading-weight); }\n\n.grayscale{filter:grayscale(1) contrast(1.08)}\n\n/* ══════════════════════════════════════════════════════════════════════════\n   Components — built with the tokens above. Plain CSS\n   on plain HTML: no JavaScript, no build step. Each class is documented in\n   readme.md and demonstrated in foundations/ and components/.\n   ══════════════════════════════════════════════════════════════════════ */\n\n*, *::before, *::after { box-sizing: border-box; }\nbody { margin: 0; font-size: 15px; line-height: 1.55; font-weight: 400; }\nh1, h2, h3, h4, h5, h6 {\n  font-family: var(--font-heading); font-weight: var(--font-heading-weight);\n  line-height: 1.12; letter-spacing: -0.015em; margin: 0 0 var(--space-2);\n}\nh1 { font-size: 42px; }\nh2 { font-size: 32px; }\nh3 { font-size: 25px; }\nh4 { font-size: 20px; }\nh5 { font-size: 16px; }\nh6 { font-size: 13px; }\nh6 { letter-spacing: 0.08em; text-transform: uppercase; }\np { margin: 0 0 var(--space-3); }\na { color: var(--color-accent); text-underline-offset: 3px; }\nimg { display: block; max-width: 100%; }\nfigure { margin: 0; }\nfigcaption {\n  font-size: 11px; margin-top: var(--space-1);\n  color: color-mix(in srgb, var(--color-text) 55%, transparent);\n}\n.text-muted { color: color-mix(in srgb, var(--color-text) 55%, transparent); }\n:focus { outline: none; }\n:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }\n::selection { background: color-mix(in srgb, var(--color-accent) 30%, transparent); }\n\n/* — rules — */\n.hr {\n  height: 2px; border: 0; margin: var(--space-4) 0;\n  background: var(--color-divider);\n}\n\n/* — buttons — */\n.btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 6px;\n  cursor: pointer; text-decoration: none;\n  font-family: var(--font-heading); font-weight: var(--font-heading-weight);\n  font-size: 14px; line-height: 1.2; color: var(--color-text); /* matches the .input's 14px —\n     the pair sits side by side in sign-up rows */\n  background: transparent; border: 1px solid transparent;\n  padding: var(--space-2) calc(var(--space-3) * 1.2);\n  border-radius: var(--radius-md);\n}\n.btn svg { display: block; }\n.btn:disabled { opacity: 0.45; cursor: not-allowed; }\n.btn-primary { background: var(--color-accent); color: var(--color-bg); }\n.btn-primary:hover { background: var(--color-accent-600); }\n.btn-primary:active { background: var(--color-accent-700); }\n.btn-secondary { border-color: var(--color-divider); }\n.btn-secondary:hover { background: color-mix(in srgb, var(--color-text) 7%, transparent); }\n.btn-secondary:active { background: color-mix(in srgb, var(--color-text) 14%, transparent); }\n.btn-ghost { color: var(--color-accent); padding-inline: var(--space-1); }\n.btn-ghost:hover { background: color-mix(in srgb, var(--color-accent) 10%, transparent); }\n.btn-ghost:active { background: color-mix(in srgb, var(--color-accent) 18%, transparent); }\n.btn-icon { width: 36px; height: 36px; padding: 0; }\n.btn-block { width: 100%; margin-top: var(--space-2); justify-content: flex-start; text-align: left; }\n\n/* — forms — */\n.field > label {\n  display: block; font-size: 12px; margin-bottom: 5px;\n  color: color-mix(in srgb, var(--color-text) 70%, transparent);\n}\n.input {\n  width: 100%; min-height: 36px; padding: 6px 10px; font: inherit;\n  font-size: 14px; color: var(--color-text); caret-color: var(--color-accent);\n  background: var(--color-surface);\n  border: 1px solid var(--color-divider); border-radius: var(--radius-md);\n}\n.input:hover { border-color: color-mix(in srgb, var(--color-text) 45%, transparent); }\n.input:focus-visible { border-color: var(--color-accent); outline-offset: 0; }\ntextarea.input { min-height: 90px; resize: vertical; }\n.radio { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-size: 14px; }\n.radio input, .seg-opt input {\n  position: absolute; opacity: 0; width: 0; height: 0; pointer-events: none;\n}\n.radio .dot {\n  width: 16px; height: 16px; flex: none; border-radius: 50%;\n  border: 1.5px solid var(--color-divider);\n}\n.radio:hover .dot { border-color: var(--color-accent); }\n.radio input:checked + .dot {\n  border-color: var(--color-accent); background: var(--color-accent);\n  box-shadow: inset 0 0 0 4px var(--color-bg);\n}\n.radio input:focus-visible + .dot { outline: 2px solid var(--color-accent); outline-offset: 2px; }\n.seg {\n  display: inline-flex; overflow: hidden;\n  border: 1px solid var(--color-divider); border-radius: var(--radius-md);\n}\n.seg-opt {\n  display: inline-flex; align-items: center; gap: 6px;\n  padding: 7px 12px; font-size: 13px; cursor: pointer;\n}\n.seg-opt + .seg-opt { border-left: 1px solid var(--color-divider); }\n.seg-opt:has(input:checked) { background: var(--color-accent); color: var(--color-bg); }\n.seg-opt:not(:has(input:checked)):hover { background: color-mix(in srgb, var(--color-text) 7%, transparent); }\n.seg-opt:has(input:focus-visible) { outline: 2px solid var(--color-accent); outline-offset: -2px; }\n\n/* — cards — */\n.card {\n  display: flex; flex-direction: column; gap: var(--space-2);\n  padding: var(--space-3); border-radius: var(--radius-md); background: var(--color-surface);\n}\n.card-kicker { font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--color-accent); }\n.card-title {\n  font-family: var(--font-heading); font-weight: var(--font-heading-weight);\n  font-size: 17px; line-height: 1.2;\n}\n.card-body { margin: 0; font-size: 13px; opacity: 0.8; flex: 1; }\n.card-meta {\n  display: flex; align-items: center; gap: 6px; font-size: 11px;\n  color: color-mix(in srgb, var(--color-text) 50%, transparent);\n}\n.elev-sm { box-shadow: var(--shadow-sm); }\n.elev-md { box-shadow: var(--shadow-md); }\n.elev-lg { box-shadow: var(--shadow-lg); }\n\n/* — tags — */\n.tag {\n  display: inline-flex; align-items: center; font-size: 11px;\n  letter-spacing: 0.02em; padding: 3px 10px;\n  border-radius: calc(var(--radius-md) * 0.75);\n}\n.tag-accent { background: var(--color-accent-100); color: var(--color-accent-800); }\n.tag-accent-2 { background: var(--color-accent-2-100); color: var(--color-accent-2-800); }\n.tag-neutral { background: var(--color-neutral-100); color: var(--color-neutral-800); }\n.tag-outline { border: 1px solid var(--color-accent); color: var(--color-accent); }\n\n/* — navigation — */\n.nav {\n  display: flex; align-items: center; gap: var(--space-4);\n  padding: var(--space-3) var(--space-4);\n  border-bottom: 2px solid var(--color-divider);\n}\n.nav-brand {\n  font-family: var(--font-heading); font-weight: var(--font-heading-weight);\n  font-size: 18px; margin-right: auto;\n}\n.nav a { color: inherit; text-decoration: none; font-size: 14px; }\n.nav a:hover, .nav a[aria-current='page'] { color: var(--color-accent); }\n\n/* — tables — */\n.table { width: 100%; border-collapse: collapse; font-size: 14px; }\n.table th {\n  text-align: left; font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase;\n  color: color-mix(in srgb, var(--color-text) 60%, transparent);\n  padding: var(--space-2); border-bottom: 2px solid var(--color-divider);\n}\n.table td {\n  padding: var(--space-2);\n  border-bottom: 1px solid var(--color-divider);\n}\n.table tbody tr:hover { background: color-mix(in srgb, var(--color-text) 4%, transparent); }\n\n/* — dialog — */\n.dialog-backdrop {\n  position: fixed; inset: 0; display: grid; place-items: center;\n  padding: var(--space-4);\n  background: color-mix(in srgb, var(--color-neutral-900) 50%, transparent);\n}\n.dialog {\n  width: min(440px, 100%); display: flex; flex-direction: column; gap: var(--space-3);\n  padding: var(--space-4); border-radius: var(--radius-lg);\n  background: var(--color-surface); box-shadow: var(--shadow-lg);\n}\n.dialog-title {\n  font-family: var(--font-heading); font-weight: var(--font-heading-weight);\n  font-size: 20px;\n}\n.dialog-body { font-size: 14px; opacity: 0.85; }\n.dialog-actions { display: flex; justify-content: flex-end; gap: var(--space-2); margin-top: var(--space-2); }\n\n<\u002Fstyle>\n<script src=\"3abef2b3-c7d3-4d4c-b65c-ea765f13ea3b\"><\u002Fscript>\n<style>\n:root{\n  --color-bg:#ffffff; --color-surface:#f5f3f4; --color-text:#201e1d;\n  --color-divider: color-mix(in srgb, #201e1d 30%, transparent);\n  --color-accent:#9e1f63; --color-accent-100:#fbeef5; --color-accent-200:#f3d6e6;\n  --color-accent-300:#e3a8c8; --color-accent-400:#c96099; --color-accent-500:#9e1f63;\n  --color-accent-600:#851950; --color-accent-700:#6b123f; --color-accent-800:#4d0c2c; --color-accent-900:#33081d;\n  --color-accent-2:#f15a29; --color-accent-2-100:#fff0ea; --color-accent-2-200:#ffd8c7;\n  --color-accent-2-500:#f15a29; --color-accent-2-600:#d1440f; --color-accent-2-700:#a13309;\n  --core-rule:1px solid var(--color-divider);\n}\nbody[data-tema=\"oscuro\"]{\n  --color-bg:#131215; --color-surface:#1c1a1f; --color-text:#f2eff1;\n  --color-divider: color-mix(in srgb, #f2eff1 26%, transparent);\n  --color-accent:#d8579b; --color-accent-100:#2a1622; --color-accent-200:#3d1d31;\n  --color-accent-600:#c14684; --color-accent-700:#e990bd;\n  --color-accent-2-100:#2e1a12; --color-accent-2-700:#f8a481;\n}\nbody{margin:0;-webkit-font-smoothing:antialiased}\na{color:var(--color-accent-700);text-decoration:none}\na:hover{color:var(--color-accent);text-decoration:underline}\ninput,button,select{font-family:var(--font-body)}\ninput::placeholder{color:color-mix(in srgb,var(--color-text) 45%,transparent)}\n::-webkit-scrollbar{width:10px;height:10px}\n::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--color-text) 22%,transparent)}\n@keyframes coreIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n<\u002Fstyle>\n<\u002Fhelmet>\n\n<div style=\"min-height:100vh;background:var(--color-bg);color:var(--color-text);font-family:var(--font-body);display:flex;flex-direction:column\">\n\n  <header style=\"position:sticky;top:0;z-index:60;display:flex;align-items:center;gap:20px;height:68px;padding:0 24px;background:var(--color-bg);border-bottom:2px solid var(--color-divider)\">\n    <button class=\"btn btn-icon\" sc-camel-on-click=\"{{ toggleNav }}\" title=\"Menú\" style=\"border:1px solid var(--color-divider)\">{{ icPanel }}<\u002Fbutton>\n    <div sc-camel-on-click=\"{{ goInicio }}\" style=\"display:flex;align-items:center;gap:12px;cursor:pointer;padding-right:20px;border-right:2px solid var(--color-divider);height:100%\">\n      <img src=\"0960b2f8-80d3-4e25-b2fb-5378a4714136\" alt=\"COREDUCACIÓN\" style=\"height:32px;width:auto\">\n      <span style=\"display:flex;flex-direction:column;line-height:1.05\">\n        <span style=\"font-family:var(--font-heading);font-weight:800;font-size:17px;letter-spacing:-0.02em\">PORTAL CORE<\u002Fspan>\n        <span style=\"font-size:9px;letter-spacing:0.22em;text-transform:uppercase;opacity:.55\">Coreducación<\u002Fspan>\n      <\u002Fspan>\n    <\u002Fdiv>\n\n    <div style=\"position:relative;flex:1;max-width:640px\">\n      <div style=\"display:flex;align-items:center;gap:10px;height:42px;padding:0 12px;background:var(--color-surface);border:1px solid var(--color-divider)\">\n        <span style=\"opacity:.6;display:flex\">{{ icSearch }}<\u002Fspan>\n        <input value=\"{{ q }}\" sc-camel-on-input=\"{{ onQ }}\" sc-camel-on-focus=\"{{ openSearch }}\" sc-camel-on-key-down=\"{{ onSearchKey }}\" placeholder=\"Buscar documentos, personas, procesos, formatos, indicadores…\" style=\"flex:1;height:40px;border:0;background:transparent;color:var(--color-text);font-size:14px;outline:none\">\n        <span style=\"font-size:10px;letter-spacing:.06em;border:1px solid var(--color-divider);padding:3px 6px;opacity:.55\">CTRL K<\u002Fspan>\n      <\u002Fdiv>\n      <sc-if value=\"{{ searchOpen }}\" hint-placeholder-val=\"{{ false }}\">\n        <div style=\"position:absolute;top:50px;left:0;right:0;background:var(--color-bg);border:1px solid var(--color-divider);box-shadow:var(--shadow-lg);max-height:60vh;overflow:auto;animation:coreIn .16s ease-out\">\n          <div style=\"display:flex;gap:6px;padding:10px 14px;border-bottom:1px solid var(--color-divider);flex-wrap:wrap\">\n            <sc-for list=\"{{ tipoChips }}\" as=\"c1\" hint-placeholder-count=\"5\">\n              <button sc-camel-on-click=\"{{ c1.onClick }}\" style=\"font-size:11px;letter-spacing:.06em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;padding:4px 9px;cursor:pointer;border:1px solid var(--color-divider);background:{{ c1.bg }};color:{{ c1.fg }}\">{{ c1.label }}<\u002Fbutton>\n            <\u002Fsc-for>\n          <\u002Fdiv>\n          <sc-for list=\"{{ quickResults }}\" as=\"r2\" hint-placeholder-count=\"6\">\n            <div sc-camel-on-click=\"{{ r2.onClick }}\" style=\"display:flex;align-items:center;gap:14px;padding:11px 16px;border-bottom:1px solid var(--color-divider);cursor:pointer\" style-hover=\"background:var(--color-surface)\">\n              <span style=\"display:flex;opacity:.7;width:18px\">{{ r2.icon }}<\u002Fspan>\n              <span style=\"flex:1;min-width:0\">\n                <span style=\"display:block;font-family:var(--font-heading);font-weight:800;font-size:14px\">{{ r2.titulo }}<\u002Fspan>\n                <span style=\"display:block;font-size:12px;opacity:.6\">{{ r2.ruta }}<\u002Fspan>\n              <\u002Fspan>\n              <span class=\"tag tag-outline\" style=\"font-size:10px;letter-spacing:.08em;text-transform:uppercase\">{{ r2.tipo }}<\u002Fspan>\n            <\u002Fdiv>\n          <\u002Fsc-for>\n          <div sc-camel-on-click=\"{{ verTodos }}\" style=\"padding:12px 16px;display:flex;align-items:center;gap:8px;cursor:pointer;font-family:var(--font-heading);font-weight:800;font-size:13px;color:var(--color-accent-700)\">\n            Ver todos los resultados {{ icArrow }}\n          <\u002Fdiv>\n        <\u002Fdiv>\n      <\u002Fsc-if>\n    <\u002Fdiv>\n\n    <div style=\"display:flex;align-items:center;gap:8px;margin-left:auto\">\n      <button class=\"btn btn-icon\" sc-camel-on-click=\"{{ toggleTema }}\" title=\"Modo claro / oscuro\" style=\"border:1px solid var(--color-divider)\">{{ icTema }}<\u002Fbutton>\n      <button class=\"btn btn-icon\" sc-camel-on-click=\"{{ openAlertas }}\" title=\"Notificaciones\" style=\"border:1px solid var(--color-divider);position:relative\">\n        {{ icBell }}\n        <span style=\"position:absolute;top:4px;right:4px;width:7px;height:7px;background:var(--color-accent-2)\"><\u002Fspan>\n      <\u002Fbutton>\n      <div sc-camel-on-click=\"{{ openPerfil }}\" style=\"display:flex;align-items:center;gap:10px;padding:6px 10px 6px 6px;border:1px solid var(--color-divider);cursor:pointer\">\n        <span style=\"width:30px;height:30px;background:var(--color-accent);color:#fff;display:flex;align-items:center;justify-content:center;font-family:var(--font-heading);font-weight:800;font-size:12px\">MR<\u002Fspan>\n        <span style=\"display:flex;flex-direction:column;line-height:1.15\">\n          <span style=\"font-size:12px;font-family:var(--font-heading);font-weight:800\">Martha Ruiz<\u002Fspan>\n          <span style=\"font-size:10px;opacity:.6\">Rectoría<\u002Fspan>\n        <\u002Fspan>\n      <\u002Fdiv>\n    <\u002Fdiv>\n  <\u002Fheader>\n\n  <div style=\"display:flex;flex:1;align-items:stretch\">\n\n    <aside style=\"width:{{ navWidth }};flex:0 0 auto;border-right:2px solid var(--color-divider);position:sticky;top:68px;height:calc(100vh - 68px);overflow-y:auto;display:{{ navDisplay }};flex-direction:column\">\n      <sc-for list=\"{{ navSections }}\" as=\"s3\" hint-placeholder-count=\"3\">\n        <div style=\"border-bottom:2px solid var(--color-divider)\">\n        <div style=\"padding:18px 0 10px\">\n          <div style=\"font-size:10px;letter-spacing:.18em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;opacity:.45;padding:0 20px 8px\">{{ s3.label }}<\u002Fdiv>\n          <sc-for list=\"{{ s3.items }}\" as=\"it4\" hint-placeholder-count=\"4\">\n            <div>\n              <div sc-camel-on-click=\"{{ it4.onClick }}\" style=\"display:flex;align-items:center;gap:12px;padding:9px 20px;cursor:pointer;border-left:3px solid {{ it4.mark }};background:{{ it4.bg }};font-family:var(--font-heading);font-weight:800;font-size:13px;color:{{ it4.fg }}\" style-hover=\"background:var(--color-surface)\">\n                <span style=\"display:flex;opacity:.85\">{{ it4.icon }}<\u002Fspan>\n                <span style=\"flex:1\">{{ it4.label }}<\u002Fspan>\n                <span style=\"display:flex;opacity:.5\">{{ it4.chev }}<\u002Fspan>\n              <\u002Fdiv>\n              <sc-if value=\"{{ it4.open }}\" hint-placeholder-val=\"{{ false }}\">\n                <div style=\"padding:2px 0 8px\">\n                  <sc-for list=\"{{ it4.children }}\" as=\"ch5\" hint-placeholder-count=\"3\">\n                    <div sc-camel-on-click=\"{{ ch5.onClick }}\" style=\"padding:6px 20px 6px 55px;font-size:12.5px;cursor:pointer;color:{{ ch5.fg }};border-left:3px solid transparent\" style-hover=\"background:var(--color-surface)\">{{ ch5.label }}<\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n              <\u002Fsc-if>\n            <\u002Fdiv>\n          <\u002Fsc-for>\n        <\u002Fdiv>\n        <\u002Fdiv>\n      <\u002Fsc-for>\n      <div style=\"margin-top:auto;padding:18px 20px;font-size:11px;opacity:.5;line-height:1.5\">\n        Portal CORE v1.0<br>Sistema Nervioso Digital<br>COREDUCACIÓN · Honda, Tolima\n      <\u002Fdiv>\n    <\u002Faside>\n\n    <main style=\"flex:1;min-width:0;display:flex;flex-direction:column\">\n\n      <div style=\"display:flex;align-items:center;gap:10px;padding:14px 40px;border-bottom:1px solid var(--color-divider);font-size:12px\">\n        <sc-for list=\"{{ breadcrumb }}\" as=\"b6\" hint-placeholder-count=\"2\">\n          <span sc-camel-on-click=\"{{ b6.onClick }}\" style=\"cursor:pointer;opacity:{{ b6.op }};font-family:var(--font-heading);font-weight:800;letter-spacing:.02em\">{{ b6.label }}<\u002Fspan>\n          <span style=\"opacity:.35\">/<\u002Fspan>\n        <\u002Fsc-for>\n        <span style=\"margin-left:auto;opacity:.55\">{{ hoy }}<\u002Fspan>\n      <\u002Fdiv>\n\n      <div style=\"flex:1;padding:36px 40px 64px;max-width:1560px;width:100%\">\n\n        <sc-if value=\"{{ esInicio }}\" hint-placeholder-val=\"{{ true }}\">\n          <div>\n            <div style=\"display:flex;align-items:flex-end;justify-content:space-between;gap:32px;flex-wrap:wrap;padding-bottom:28px\">\n              <div style=\"max-width:720px\">\n                <div style=\"font-size:11px;letter-spacing:.2em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;color:var(--color-accent-700);padding-bottom:10px\">Buenos días<\u002Fdiv>\n                <h1 style=\"font-size:46px;margin:0 0 12px\">Jeiver, la institución está en marcha.<\u002Fh1>\n                <p style=\"font-size:16px;opacity:.7;max-width:620px;text-wrap:pretty;margin:0\">Tienes 4 pendientes, 2 documentos en revisión y el avance del PDI cerró la semana en 62%. Todo lo institucional, en un solo lugar.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"display:flex;gap:0;border:1px solid var(--color-divider)\">\n                <div style=\"padding:14px 20px;border-right:1px solid var(--color-divider)\">\n                  <div style=\"font-size:10px;letter-spacing:.16em;text-transform:uppercase;opacity:.55;font-family:var(--font-heading);font-weight:800\">Estado institucional<\u002Fdiv>\n                  <div style=\"display:flex;align-items:center;gap:8px;padding-top:6px;font-family:var(--font-heading);font-weight:800;font-size:15px\"><span style=\"width:9px;height:9px;background:var(--color-accent-2)\"><\u002Fspan>Operación normal<\u002Fdiv>\n                <\u002Fdiv>\n                <div style=\"padding:14px 20px\">\n                  <div style=\"font-size:10px;letter-spacing:.16em;text-transform:uppercase;opacity:.55;font-family:var(--font-heading);font-weight:800\">Ciclo<\u002Fdiv>\n                  <div style=\"padding-top:6px;font-family:var(--font-heading);font-weight:800;font-size:15px\">2026 · Semestre II<\u002Fdiv>\n                <\u002Fdiv>\n              <\u002Fdiv>\n            <\u002Fdiv>\n\n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));border:1px solid var(--color-divider);border-bottom:2px solid var(--color-divider)\">\n              <sc-for list=\"{{ kpis }}\" as=\"k7\" hint-placeholder-count=\"5\">\n                <div style=\"padding:22px 24px;border-right:1px solid var(--color-divider)\">\n                  <div style=\"font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;opacity:.55\">{{ k7.label }}<\u002Fdiv>\n                  <div style=\"font-family:var(--font-heading);font-weight:800;font-size:34px;letter-spacing:-0.03em;padding:10px 0 4px\">{{ k7.valor }}<\u002Fdiv>\n                  <div style=\"font-size:12px;color:var(--color-accent-700);font-family:var(--font-heading);font-weight:800\">{{ k7.delta }}<\u002Fdiv>\n                <\u002Fdiv>\n              <\u002Fsc-for>\n            <\u002Fdiv>\n\n            <div style=\"display:grid;grid-template-columns:1.6fr 1fr;gap:40px;padding-top:40px;align-items:start\">\n              <div>\n                <div style=\"display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid var(--color-divider);padding-bottom:10px;margin-bottom:20px\">\n                  <h4 style=\"margin:0\">Accesos rápidos<\u002Fh4>\n                  <span sc-camel-on-click=\"{{ goApps }}\" style=\"font-size:12px;cursor:pointer;color:var(--color-accent-700);font-family:var(--font-heading);font-weight:800\">Centro de aplicaciones<\u002Fspan>\n                <\u002Fdiv>\n                <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:1px;background:var(--color-divider);border:1px solid var(--color-divider)\">\n                  <sc-for list=\"{{ accesos }}\" as=\"a8\" hint-placeholder-count=\"8\">\n                    <div sc-camel-on-click=\"{{ a8.onClick }}\" style=\"background:var(--color-bg);padding:18px 16px;cursor:pointer;display:flex;flex-direction:column;gap:12px;min-height:112px\" style-hover=\"background:var(--color-surface)\">\n                      <span style=\"display:flex;color:var(--color-accent)\">{{ a8.icon }}<\u002Fspan>\n                      <span style=\"font-family:var(--font-heading);font-weight:800;font-size:13px;line-height:1.25\">{{ a8.label }}<\u002Fspan>\n                      <span style=\"font-size:11px;opacity:.5;margin-top:auto\">{{ a8.meta }}<\u002Fspan>\n                    <\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n\n                <div style=\"display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid var(--color-divider);padding-bottom:10px;margin:44px 0 0\">\n                  <h4 style=\"margin:0\">Documentos recientes<\u002Fh4>\n                  <span sc-camel-on-click=\"{{ goDoc }}\" style=\"font-size:12px;cursor:pointer;color:var(--color-accent-700);font-family:var(--font-heading);font-weight:800\">Repositorio<\u002Fspan>\n                <\u002Fdiv>\n                <sc-raw-table class=\"table\" style=\"width:100%\">\n                  <sc-raw-thead><sc-raw-tr><sc-raw-th>Documento<\u002Fsc-raw-th><sc-raw-th>Área<\u002Fsc-raw-th><sc-raw-th>Ver.<\u002Fsc-raw-th><sc-raw-th>Actualizado<\u002Fsc-raw-th><\u002Fsc-raw-tr><\u002Fsc-raw-thead>\n                  <sc-raw-tbody>\n                    <sc-for list=\"{{ docsRecientes }}\" as=\"d9\" hint-placeholder-count=\"5\">\n                      <sc-raw-tr sc-camel-on-click=\"{{ d9.onClick }}\" style=\"cursor:pointer\">\n                        <sc-raw-td><span style=\"display:flex;align-items:center;gap:10px\"><span style=\"display:flex;opacity:.6\">{{ d9.icon }}<\u002Fspan><span style=\"font-family:var(--font-heading);font-weight:800\">{{ d9.nombre }}<\u002Fspan><\u002Fspan><\u002Fsc-raw-td>\n                        <sc-raw-td style=\"opacity:.7\">{{ d9.area }}<\u002Fsc-raw-td>\n                        <sc-raw-td><span class=\"tag tag-neutral\" style=\"font-size:10px\">{{ d9.version }}<\u002Fspan><\u002Fsc-raw-td>\n                        <sc-raw-td style=\"opacity:.7\">{{ d9.fecha }}<\u002Fsc-raw-td>\n                      <\u002Fsc-raw-tr>\n                    <\u002Fsc-for>\n                  <\u002Fsc-raw-tbody>\n                <\u002Fsc-raw-table>\n\n                <div style=\"border-bottom:2px solid var(--color-divider);padding-bottom:10px;margin:44px 0 20px\"><h4 style=\"margin:0\">Novedades institucionales<\u002Fh4><\u002Fdiv>\n                <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:24px\">\n                  <sc-for list=\"{{ noticias }}\" as=\"n10\" hint-placeholder-count=\"3\">\n                    <div class=\"card\" style=\"padding:0;display:flex;flex-direction:column\">\n                      <div class=\"grayscale\" style=\"height:130px;background:var(--color-neutral-300);display:flex;align-items:flex-end;padding:10px;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--color-neutral-700)\">{{ n10.foto }}<\u002Fdiv>\n                      <div style=\"padding:16px 18px 18px\">\n                        <div class=\"card-kicker\" style=\"font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--color-accent-700);font-family:var(--font-heading);font-weight:800\">{{ n10.categoria }}<\u002Fdiv>\n                        <div style=\"font-family:var(--font-heading);font-weight:800;font-size:16px;line-height:1.2;padding:8px 0 8px;text-wrap:pretty\">{{ n10.titulo }}<\u002Fdiv>\n                        <div style=\"font-size:12px;opacity:.55\">{{ n10.fecha }}<\u002Fdiv>\n                      <\u002Fdiv>\n                    <\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n              <\u002Fdiv>\n\n              <div style=\"display:flex;flex-direction:column;gap:36px\">\n                <div>\n                  <div style=\"border-bottom:2px solid var(--color-divider);padding-bottom:10px;margin-bottom:6px\"><h4 style=\"margin:0\">Mis pendientes<\u002Fh4><\u002Fdiv>\n                  <sc-for list=\"{{ pendientes }}\" as=\"p11\" hint-placeholder-count=\"4\">\n                    <div style=\"display:flex;gap:12px;padding:13px 0;border-bottom:1px solid var(--color-divider);align-items:flex-start\">\n                      <span style=\"width:8px;height:8px;margin-top:6px;flex:0 0 auto;background:{{ p11.color }}\"><\u002Fspan>\n                      <span style=\"flex:1\">\n                        <span style=\"display:block;font-family:var(--font-heading);font-weight:800;font-size:13px\">{{ p11.titulo }}<\u002Fspan>\n                        <span style=\"display:block;font-size:11.5px;opacity:.6;padding-top:2px\">{{ p11.meta }}<\u002Fspan>\n                      <\u002Fspan>\n                    <\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n\n                <div>\n                  <div style=\"border-bottom:2px solid var(--color-divider);padding-bottom:10px;margin-bottom:6px\"><h4 style=\"margin:0\">Agenda de la semana<\u002Fh4><\u002Fdiv>\n                  <sc-for list=\"{{ eventos }}\" as=\"e12\" hint-placeholder-count=\"4\">\n                    <div style=\"display:flex;gap:16px;padding:13px 0;border-bottom:1px solid var(--color-divider)\">\n                      <span style=\"width:46px;flex:0 0 auto;text-align:left\">\n                        <span style=\"display:block;font-family:var(--font-heading);font-weight:800;font-size:19px;line-height:1\">{{ e12.dia }}<\u002Fspan>\n                        <span style=\"display:block;font-size:10px;letter-spacing:.12em;text-transform:uppercase;opacity:.55\">{{ e12.mes }}<\u002Fspan>\n                      <\u002Fspan>\n                      <span style=\"flex:1\">\n                        <span style=\"display:block;font-family:var(--font-heading);font-weight:800;font-size:13px\">{{ e12.titulo }}<\u002Fspan>\n                        <span style=\"display:block;font-size:11.5px;opacity:.6\">{{ e12.hora }}<\u002Fspan>\n                      <\u002Fspan>\n                    <\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n\n                <div>\n                  <div style=\"border-bottom:2px solid var(--color-divider);padding-bottom:10px;margin-bottom:6px\"><h4 style=\"margin:0\">Cumpleaños<\u002Fh4><\u002Fdiv>\n                  <sc-for list=\"{{ cumpleanos }}\" as=\"c13\" hint-placeholder-count=\"3\">\n                    <div style=\"display:flex;gap:12px;align-items:center;padding:11px 0;border-bottom:1px solid var(--color-divider)\">\n                      <span style=\"width:30px;height:30px;flex:0 0 auto;background:var(--color-accent-200);color:var(--color-accent-800);display:flex;align-items:center;justify-content:center;font-family:var(--font-heading);font-weight:800;font-size:11px\">{{ c13.ini }}<\u002Fspan>\n                      <span style=\"flex:1;font-size:13px;font-family:var(--font-heading);font-weight:800\">{{ c13.nombre }}<\u002Fspan>\n                      <span style=\"font-size:11px;opacity:.6\">{{ c13.fecha }}<\u002Fspan>\n                    <\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n\n                <div style=\"background:var(--color-accent);color:#fff;padding:26px 24px\">\n                  <div style=\"font-size:10px;letter-spacing:.2em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;opacity:.8\">Plan de Desarrollo Institucional<\u002Fdiv>\n                  <div style=\"font-family:var(--font-heading);font-weight:800;font-size:52px;letter-spacing:-0.04em;line-height:1;padding:14px 0 6px\">62%<\u002Fdiv>\n                  <div style=\"height:6px;background:rgba(255,255,255,.3);margin:8px 0 14px\"><div style=\"width:62%;height:6px;background:#fff\"><\u002Fdiv><\u002Fdiv>\n                  <div style=\"font-size:13px;opacity:.9;text-wrap:pretty\">Avance acumulado 2026 sobre 48 metas cascadeadas a 11 áreas.<\u002Fdiv>\n                <\u002Fdiv>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fdiv>\n        <\u002Fsc-if>\n\n        <sc-if value=\"{{ esTableros }}\" hint-placeholder-val=\"{{ false }}\">\n          <div>\n            <h1 style=\"font-size:40px;margin:0 0 8px\">Tableros Estratégicos<\u002Fh1>\n            <p style=\"opacity:.65;max-width:640px;margin:0 0 28px\">Indicadores institucionales en tiempo real. Vista Rectoría, con descenso a dirección y área.<\u002Fp>\n            <div style=\"display:flex;gap:0;border:1px solid var(--color-divider);width:fit-content;margin-bottom:28px\">\n              <sc-for list=\"{{ tableroTabs }}\" as=\"t14\" hint-placeholder-count=\"4\">\n                <button sc-camel-on-click=\"{{ t14.onClick }}\" style=\"padding:10px 18px;border:0;border-right:1px solid var(--color-divider);cursor:pointer;font-family:var(--font-heading);font-weight:800;font-size:12.5px;background:{{ t14.bg }};color:{{ t14.fg }}\">{{ t14.label }}<\u002Fbutton>\n              <\u002Fsc-for>\n            <\u002Fdiv>\n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));border:1px solid var(--color-divider);border-bottom:2px solid var(--color-divider);margin-bottom:36px\">\n              <sc-for list=\"{{ kpisTablero }}\" as=\"k15\" hint-placeholder-count=\"4\">\n                <div style=\"padding:22px 24px;border-right:1px solid var(--color-divider)\">\n                  <div style=\"font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;opacity:.55\">{{ k15.label }}<\u002Fdiv>\n                  <div style=\"font-family:var(--font-heading);font-weight:800;font-size:32px;letter-spacing:-0.03em;padding:10px 0 4px\">{{ k15.valor }}<\u002Fdiv>\n                  <div style=\"font-size:12px;opacity:.6\">Meta {{ k15.meta }}<\u002Fdiv>\n                  <div style=\"height:5px;background:var(--color-surface);margin-top:10px\"><div style=\"height:5px;background:var(--color-accent);width:{{ k15.pct }}\"><\u002Fdiv><\u002Fdiv>\n                <\u002Fdiv>\n              <\u002Fsc-for>\n            <\u002Fdiv>\n            <div style=\"display:grid;grid-template-columns:1.3fr 1fr;gap:36px;align-items:start\">\n              <div style=\"border:1px solid var(--color-divider);padding:24px\">\n                <div style=\"display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid var(--color-divider);padding-bottom:12px;margin-bottom:24px\">\n                  <h4 style=\"margin:0\">Matrícula por facultad · 2026-II<\u002Fh4>\n                  <span style=\"font-size:11px;letter-spacing:.1em;text-transform:uppercase;opacity:.5;font-family:var(--font-heading);font-weight:800\">Power BI · en vivo<\u002Fspan>\n                <\u002Fdiv>\n                <div style=\"display:flex;align-items:flex-end;gap:18px;height:230px\">\n                  <sc-for list=\"{{ barras }}\" as=\"b16\" hint-placeholder-count=\"6\">\n                    <div style=\"flex:1;display:flex;flex-direction:column;justify-content:flex-end;gap:8px;height:100%\">\n                      <span style=\"font-family:var(--font-heading);font-weight:800;font-size:13px\">{{ b16.valor }}<\u002Fspan>\n                      <span style=\"background:var(--color-accent);height:{{ b16.h }}\"><\u002Fspan>\n                      <span style=\"font-size:10.5px;opacity:.6;line-height:1.2;min-height:26px\">{{ b16.label }}<\u002Fspan>\n                    <\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n              <\u002Fdiv>\n              <div style=\"display:flex;flex-direction:column;gap:24px\">\n                <div style=\"border:1px solid var(--color-divider);padding:24px\">\n                  <h4 style=\"margin:0 0 18px\">Ejecución presupuestal<\u002Fh4>\n                  <sc-for list=\"{{ ejecucion }}\" as=\"e17\" hint-placeholder-count=\"4\">\n                    <div style=\"padding:9px 0\">\n                      <div style=\"display:flex;justify-content:space-between;font-size:12.5px;padding-bottom:6px\"><span>{{ e17.label }}<\u002Fspan><span style=\"font-family:var(--font-heading);font-weight:800\">{{ e17.pct }}<\u002Fspan><\u002Fdiv>\n                      <div style=\"height:6px;background:var(--color-surface)\"><div style=\"height:6px;background:var(--color-accent-2);width:{{ e17.pct }}\"><\u002Fdiv><\u002Fdiv>\n                    <\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n                <div style=\"border:1px solid var(--color-divider);padding:24px\">\n                  <h4 style=\"margin:0 0 14px\">Alertas de indicador<\u002Fh4>\n                  <sc-for list=\"{{ alertasKpi }}\" as=\"a18\" hint-placeholder-count=\"3\">\n                    <div style=\"display:flex;gap:12px;padding:11px 0;border-top:1px solid var(--color-divider)\">\n                      <span style=\"display:flex;color:var(--color-accent-2);flex:0 0 auto\">{{ a18.icon }}<\u002Fspan>\n                      <span style=\"font-size:12.5px;flex:1;text-wrap:pretty\">{{ a18.texto }}<\u002Fspan>\n                    <\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fdiv>\n        <\u002Fsc-if>\n\n        <sc-if value=\"{{ esSitemap }}\" hint-placeholder-val=\"{{ false }}\">\n          <div>\n            <h1 style=\"font-size:40px;margin:0 0 8px\">Arquitectura de información<\u002Fh1>\n            <p style=\"opacity:.65;max-width:700px;margin:0 0 34px\">El Portal CORE replica la estructura organizacional de COREDUCACIÓN: cada Dirección es un módulo, cada área un espacio de trabajo con su documentación, indicadores y responsables. Máximo tres clics hasta cualquier contenido.<\u002Fp>\n            <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:1px;background:var(--color-divider);border:1px solid var(--color-divider)\">\n              <sc-for list=\"{{ sitemap }}\" as=\"m19\" hint-placeholder-count=\"8\">\n                <div style=\"background:var(--color-bg);padding:24px 22px 26px;display:flex;flex-direction:column\">\n                  <div style=\"display:flex;align-items:center;gap:10px;color:var(--color-accent)\">{{ m19.icon }}<span style=\"font-size:10px;letter-spacing:.16em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800\">{{ m19.nivel }}<\u002Fspan><\u002Fdiv>\n                  <div sc-camel-on-click=\"{{ m19.onClick }}\" style=\"font-family:var(--font-heading);font-weight:800;font-size:19px;line-height:1.15;padding:12px 0 14px;cursor:pointer;text-wrap:pretty\">{{ m19.label }}<\u002Fdiv>\n                  <div style=\"height:2px;background:var(--color-divider);margin-bottom:12px\"><\u002Fdiv>\n                  <sc-for list=\"{{ m19.hijos }}\" as=\"h20\" hint-placeholder-count=\"5\">\n                    <div sc-camel-on-click=\"{{ h20.onClick }}\" style=\"font-size:12.5px;padding:5px 0;cursor:pointer;opacity:.75\" style-hover=\"opacity:1;color:var(--color-accent-700)\">{{ h20.label }}<\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n              <\u002Fsc-for>\n            <\u002Fdiv>\n            <div style=\"margin-top:48px;border-top:2px solid var(--color-divider);padding-top:26px\">\n              <h4 style=\"margin:0 0 16px\">Contenido tipo de cada área<\u002Fh4>\n              <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n                <sc-for list=\"{{ contenidoTipo }}\" as=\"c21\" hint-placeholder-count=\"18\">\n                  <span class=\"tag tag-outline\" style=\"font-size:11.5px\">{{ c21 }}<\u002Fspan>\n                <\u002Fsc-for>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fdiv>\n        <\u002Fsc-if>\n\n        <sc-if value=\"{{ esDocumental }}\" hint-placeholder-val=\"{{ false }}\">\n          <div>\n            <div style=\"display:flex;align-items:flex-end;justify-content:space-between;gap:24px;flex-wrap:wrap;margin-bottom:26px\">\n              <div>\n                <h1 style=\"font-size:40px;margin:0 0 8px\">Gestión Documental<\u002Fh1>\n                <p style=\"opacity:.65;margin:0;max-width:560px\">Repositorio institucional con control de versiones, vigencia y responsable por documento.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"display:flex;gap:8px\">\n                <button class=\"btn btn-secondary\" sc-camel-on-click=\"{{ noop }}\">{{ icFilter }} Filtros<\u002Fbutton>\n                <button class=\"btn btn-primary\" sc-camel-on-click=\"{{ noop }}\">{{ icPlus }} Cargar documento<\u002Fbutton>\n              <\u002Fdiv>\n            <\u002Fdiv>\n            <div style=\"display:grid;grid-template-columns:280px 1fr;border:1px solid var(--color-divider);align-items:stretch\">\n              <div style=\"border-right:2px solid var(--color-divider);padding:18px 0\">\n                <div style=\"font-size:10px;letter-spacing:.16em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;opacity:.45;padding:0 18px 10px\">Árbol documental<\u002Fdiv>\n                <sc-for list=\"{{ arbol }}\" as=\"n22\" hint-placeholder-count=\"6\">\n                  <div>\n                    <div sc-camel-on-click=\"{{ n22.onClick }}\" style=\"display:flex;align-items:center;gap:9px;padding:8px 18px;cursor:pointer;font-size:12.5px;font-family:var(--font-heading);font-weight:800;background:{{ n22.bg }}\" style-hover=\"background:var(--color-surface)\">\n                      <span style=\"display:flex;opacity:.55\">{{ n22.chev }}<\u002Fspan>\n                      <span style=\"display:flex;color:var(--color-accent)\">{{ icFolderSm }}<\u002Fspan>\n                      <span style=\"flex:1;text-wrap:pretty;line-height:1.2\">{{ n22.label }}<\u002Fspan>\n                    <\u002Fdiv>\n                    <sc-if value=\"{{ n22.open }}\" hint-placeholder-val=\"{{ false }}\">\n                      <div style=\"padding-bottom:6px\">\n                        <sc-for list=\"{{ n22.hijos }}\" as=\"h23\" hint-placeholder-count=\"3\">\n                          <div sc-camel-on-click=\"{{ h23.onClick }}\" style=\"display:flex;gap:8px;padding:6px 18px 6px 44px;font-size:12px;cursor:pointer;color:{{ h23.fg }}\" style-hover=\"background:var(--color-surface)\">{{ h23.label }}<\u002Fdiv>\n                        <\u002Fsc-for>\n                      <\u002Fdiv>\n                    <\u002Fsc-if>\n                  <\u002Fdiv>\n                <\u002Fsc-for>\n              <\u002Fdiv>\n              <div>\n                <div style=\"display:flex;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid var(--color-divider);flex-wrap:wrap\">\n                  <span style=\"font-family:var(--font-heading);font-weight:800;font-size:13px\">{{ carpetaActual }}<\u002Fspan>\n                  <span style=\"font-size:12px;opacity:.55\">{{ archivosCount }} elementos<\u002Fspan>\n                  <div style=\"display:flex;margin-left:auto;border:1px solid var(--color-divider)\">\n                    <sc-for list=\"{{ vistaTabs }}\" as=\"v24\" hint-placeholder-count=\"3\">\n                      <button sc-camel-on-click=\"{{ v24.onClick }}\" style=\"display:flex;align-items:center;gap:7px;padding:7px 13px;border:0;border-right:1px solid var(--color-divider);cursor:pointer;font-family:var(--font-heading);font-weight:800;font-size:11.5px;background:{{ v24.bg }};color:{{ v24.fg }}\">{{ v24.icon }}{{ v24.label }}<\u002Fbutton>\n                    <\u002Fsc-for>\n                  <\u002Fdiv>\n                <\u002Fdiv>\n\n                <sc-if value=\"{{ vistaTabla }}\" hint-placeholder-val=\"{{ true }}\">\n                  <sc-raw-table class=\"table\" style=\"width:100%\">\n                    <sc-raw-thead><sc-raw-tr><sc-raw-th>Nombre<\u002Fsc-raw-th><sc-raw-th>Tipo<\u002Fsc-raw-th><sc-raw-th>Ver.<\u002Fsc-raw-th><sc-raw-th>Vigencia<\u002Fsc-raw-th><sc-raw-th>Responsable<\u002Fsc-raw-th><sc-raw-th>Actualizado<\u002Fsc-raw-th><\u002Fsc-raw-tr><\u002Fsc-raw-thead>\n                    <sc-raw-tbody>\n                      <sc-for list=\"{{ archivos }}\" as=\"f25\" hint-placeholder-count=\"8\">\n                        <sc-raw-tr sc-camel-on-click=\"{{ f25.onClick }}\" style=\"cursor:pointer;background:{{ f25.bg }}\">\n                          <sc-raw-td><span style=\"display:flex;align-items:center;gap:10px\"><span style=\"display:flex;color:var(--color-accent)\">{{ f25.icon }}<\u002Fspan><span style=\"font-family:var(--font-heading);font-weight:800\">{{ f25.nombre }}<\u002Fspan><\u002Fspan><\u002Fsc-raw-td>\n                          <sc-raw-td style=\"opacity:.7\">{{ f25.tipo }}<\u002Fsc-raw-td>\n                          <sc-raw-td><span class=\"tag tag-neutral\" style=\"font-size:10px\">{{ f25.version }}<\u002Fspan><\u002Fsc-raw-td>\n                          <sc-raw-td>{{ f25.estadoTag }}<\u002Fsc-raw-td>\n                          <sc-raw-td style=\"opacity:.7\">{{ f25.responsable }}<\u002Fsc-raw-td>\n                          <sc-raw-td style=\"opacity:.7\">{{ f25.fecha }}<\u002Fsc-raw-td>\n                        <\u002Fsc-raw-tr>\n                      <\u002Fsc-for>\n                    <\u002Fsc-raw-tbody>\n                  <\u002Fsc-raw-table>\n                <\u002Fsc-if>\n\n                <sc-if value=\"{{ vistaExplorador }}\" hint-placeholder-val=\"{{ false }}\">\n                  <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:1px;background:var(--color-divider);padding:1px\">\n                    <sc-for list=\"{{ archivos }}\" as=\"f26\" hint-placeholder-count=\"8\">\n                      <div sc-camel-on-click=\"{{ f26.onClick }}\" style=\"background:var(--color-bg);padding:20px 18px;cursor:pointer;display:flex;flex-direction:column;gap:14px;min-height:150px\" style-hover=\"background:var(--color-surface)\">\n                        <span style=\"display:flex;color:var(--color-accent)\">{{ f26.iconBig }}<\u002Fspan>\n                        <span style=\"font-family:var(--font-heading);font-weight:800;font-size:13px;line-height:1.25;text-wrap:pretty\">{{ f26.nombre }}<\u002Fspan>\n                        <span style=\"margin-top:auto;font-size:11px;opacity:.55\">{{ f26.version }} · {{ f26.fecha }}<\u002Fspan>\n                      <\u002Fdiv>\n                    <\u002Fsc-for>\n                  <\u002Fdiv>\n                <\u002Fsc-if>\n\n                <sc-if value=\"{{ vistaLista }}\" hint-placeholder-val=\"{{ false }}\">\n                  <div style=\"padding:8px 0\">\n                    <sc-for list=\"{{ archivos }}\" as=\"f27\" hint-placeholder-count=\"8\">\n                      <div sc-camel-on-click=\"{{ f27.onClick }}\" style=\"display:flex;align-items:center;gap:14px;padding:14px 20px;border-bottom:1px solid var(--color-divider);cursor:pointer\" style-hover=\"background:var(--color-surface)\">\n                        <span style=\"display:flex;opacity:.6\">{{ f27.icon }}<\u002Fspan>\n                        <span style=\"flex:1\">\n                          <span style=\"display:block;font-family:var(--font-heading);font-weight:800;font-size:14px\">{{ f27.nombre }}<\u002Fspan>\n                          <span style=\"display:block;font-size:11.5px;opacity:.6\">{{ f27.tipo }} · {{ f27.responsable }} · {{ f27.fecha }}<\u002Fspan>\n                        <\u002Fspan>\n                        {{ f27.estadoTag }}\n                      <\u002Fdiv>\n                    <\u002Fsc-for>\n                  <\u002Fdiv>\n                <\u002Fsc-if>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fdiv>\n        <\u002Fsc-if>\n\n        <sc-if value=\"{{ esBuscador }}\" hint-placeholder-val=\"{{ false }}\">\n          <div>\n            <div style=\"border-bottom:2px solid var(--color-divider);padding-bottom:22px;margin-bottom:26px\">\n              <div style=\"font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;color:var(--color-accent-700);padding-bottom:10px\">Buscador inteligente<\u002Fdiv>\n              <h1 style=\"font-size:38px;margin:0 0 6px\">{{ tituloBusqueda }}<\u002Fh1>\n              <p style=\"opacity:.6;margin:0\">{{ resumenBusqueda }}<\u002Fp>\n            <\u002Fdiv>\n            <div style=\"display:grid;grid-template-columns:1fr 300px;gap:40px;align-items:start\">\n              <div>\n                <div style=\"display:flex;gap:6px;flex-wrap:wrap;margin-bottom:20px\">\n                  <sc-for list=\"{{ tipoChips }}\" as=\"c28\" hint-placeholder-count=\"6\">\n                    <button sc-camel-on-click=\"{{ c28.onClick }}\" style=\"font-size:11px;letter-spacing:.06em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;padding:6px 11px;cursor:pointer;border:1px solid var(--color-divider);background:{{ c28.bg }};color:{{ c28.fg }}\">{{ c28.label }}<\u002Fbutton>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n                <sc-for list=\"{{ resultados }}\" as=\"r29\" hint-placeholder-count=\"8\">\n                  <div sc-camel-on-click=\"{{ r29.onClick }}\" style=\"display:flex;gap:18px;padding:20px 0;border-bottom:1px solid var(--color-divider);cursor:pointer\" style-hover=\"background:var(--color-surface)\">\n                    <span style=\"display:flex;color:var(--color-accent);flex:0 0 auto;padding-top:2px\">{{ r29.iconBig }}<\u002Fspan>\n                    <span style=\"flex:1;min-width:0\">\n                      <span style=\"display:flex;align-items:center;gap:10px;padding-bottom:4px\">\n                        <span class=\"tag tag-accent\" style=\"font-size:10px;letter-spacing:.1em;text-transform:uppercase\">{{ r29.tipo }}<\u002Fspan>\n                        <span style=\"font-size:11.5px;opacity:.55\">{{ r29.ruta }}<\u002Fspan>\n                      <\u002Fspan>\n                      <span style=\"display:block;font-family:var(--font-heading);font-weight:800;font-size:17px;line-height:1.2\">{{ r29.titulo }}<\u002Fspan>\n                      <span style=\"display:block;font-size:13px;opacity:.65;padding-top:5px;text-wrap:pretty\">{{ r29.desc }}<\u002Fspan>\n                    <\u002Fspan>\n                    <span style=\"flex:0 0 auto;font-size:11.5px;opacity:.5;text-align:right\">{{ r29.meta }}<\u002Fspan>\n                  <\u002Fdiv>\n                <\u002Fsc-for>\n                <sc-if value=\"{{ sinResultados }}\" hint-placeholder-val=\"{{ false }}\">\n                  <div style=\"padding:56px 0;text-align:left;opacity:.6\">\n                    <div style=\"font-family:var(--font-heading);font-weight:800;font-size:18px\">Sin coincidencias.<\u002Fdiv>\n                    <div style=\"font-size:13px;padding-top:6px\">Prueba con «manual de funciones», «riesgos», «tesorería» o el nombre de una persona.<\u002Fdiv>\n                  <\u002Fdiv>\n                <\u002Fsc-if>\n              <\u002Fdiv>\n              <div style=\"border:1px solid var(--color-divider);padding:22px\">\n                <div style=\"font-size:10px;letter-spacing:.16em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;opacity:.5;padding-bottom:14px\">Refinar<\u002Fdiv>\n                <sc-for list=\"{{ facetas }}\" as=\"f30\" hint-placeholder-count=\"4\">\n                  <div style=\"padding:9px 0;border-top:1px solid var(--color-divider);display:flex;justify-content:space-between;font-size:12.5px\">\n                    <span>{{ f30.label }}<\u002Fspan><span style=\"opacity:.55\">{{ f30.n }}<\u002Fspan>\n                  <\u002Fdiv>\n                <\u002Fsc-for>\n                <div style=\"margin-top:24px;padding-top:18px;border-top:2px solid var(--color-divider)\">\n                  <div style=\"font-size:10px;letter-spacing:.16em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;opacity:.5;padding-bottom:10px\">Búsquedas frecuentes<\u002Fdiv>\n                  <sc-for list=\"{{ sugerencias }}\" as=\"s31\" hint-placeholder-count=\"5\">\n                    <div sc-camel-on-click=\"{{ s31.onClick }}\" style=\"font-size:12.5px;padding:5px 0;cursor:pointer;color:var(--color-accent-700)\">{{ s31.label }}<\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fdiv>\n        <\u002Fsc-if>\n\n        <sc-if value=\"{{ esTalento }}\" hint-placeholder-val=\"{{ false }}\">\n          <div>\n            <h1 style=\"font-size:40px;margin:0 0 8px\">Talento Humano<\u002Fh1>\n            <p style=\"opacity:.65;max-width:640px;margin:0 0 26px\">Gestión Humana y Desarrollo Organizacional. Estructura, funciones, desempeño y bienestar en un solo espacio.<\u002Fp>\n            <div style=\"display:flex;border:1px solid var(--color-divider);width:fit-content;margin-bottom:34px;flex-wrap:wrap\">\n              <sc-for list=\"{{ talentoTabs }}\" as=\"t32\" hint-placeholder-count=\"4\">\n                <button sc-camel-on-click=\"{{ t32.onClick }}\" style=\"padding:10px 18px;border:0;border-right:1px solid var(--color-divider);cursor:pointer;font-family:var(--font-heading);font-weight:800;font-size:12.5px;background:{{ t32.bg }};color:{{ t32.fg }}\">{{ t32.label }}<\u002Fbutton>\n              <\u002Fsc-for>\n            <\u002Fdiv>\n\n            <sc-if value=\"{{ tabOrgani