sc-if value=\"{{ esModulo }}\" hint-placeholder-val=\"{{ false }}\">\n          <div>\n            <div style=\"border-bottom:2px solid var(--color-divider);padding-bottom:24px;margin-bottom:30px\">\n              <div style=\"font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;color:var(--color-accent-700);padding-bottom:10px\">{{ modulo.kicker }}<\u002Fdiv>\n              <h1 style=\"font-size:40px;margin:0 0 10px\">{{ modulo.titulo }}<\u002Fh1>\n              <p style=\"opacity:.65;max-width:700px;margin:0\">{{ modulo.desc }}<\u002Fp>\n            <\u002Fdiv>\n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));border:1px solid var(--color-divider);margin-bottom:36px\">\n              <sc-for list=\"{{ modulo.kpis }}\" as=\"k44\" hint-placeholder-count=\"4\">\n                <div style=\"padding:20px 22px;border-right:1px solid var(--color-divider)\">\n                  <div style=\"font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;font-family:var(--font-heading);font-weight:800;opacity:.55\">{{ k44.label }}<\u002Fdiv>\n                  <div style=\"font-family:var(--font-heading);font-weight:800;font-size:30px;letter-spacing:-0.03em;padding-top:8px\">{{ k44.valor }}<\u002Fdiv>\n                <\u002Fdiv>\n              <\u002Fsc-for>\n            <\u002Fdiv>\n            <div style=\"display:grid;grid-template-columns:1fr 320px;gap:40px;align-items:start\">\n              <div>\n                <div style=\"border-bottom:2px solid var(--color-divider);padding-bottom:10px;margin-bottom:2px\"><h4 style=\"margin:0\">Áreas del módulo<\u002Fh4><\u002Fdiv>\n                <sc-for list=\"{{ modulo.areas }}\" as=\"a45\" hint-placeholder-count=\"4\">\n                  <div sc-camel-on-click=\"{{ a45.onClick }}\" style=\"display:flex;gap:18px;padding:18px 0;border-bottom:1px solid var(--color-divider);cursor:pointer\" style-hover=\"background:var(--color-s